import{j as e}from"./index-BULR-rtU.js";function i(){const a=[{q:"What is Axnna?",a:"Axnna is an automated market-analysis engine. It monitors financial markets 24/5, evaluates structural alignment using a purely deterministic pipeline, and delivers formatted setup signals natively through Telegram."},{q:"How does Axnna work?",a:"Axnna constantly processes market candles, tracks liquidity pools, computes structural displacement, and normalizes fundamental macroeconomic data. When all geometric and contextual conditions align according to our internal strategy definitions, a notification is generated."},{q:"Where do I receive signals?",a:"All eligible signals are delivered strictly through the official Axnna Telegram bot. We do not use email or SMS."},{q:"Does Axnna execute trades automatically?",a:"No. Axnna is purely an analytical notification layer. It does not execute trades, manage margin, or connect to your broker. You are entirely responsible for your own execution and risk management."},{q:"What does the signal score mean?",a:"The Axnna Score (e.g., 78%) is an internal confidence metric representing how closely a setup aligns with our ideal structural and fundamental geometry."},{q:"Why is 65% the minimum score?",a:"Axnna filters out noise. Any setup that scores below our strict 65% threshold is silently discarded to protect you from low-quality structures. You only hear from us when the numbers align."},{q:"Does a 65% score mean a trade has a 65% chance of winning?",a:"NO. The Axnna score is an internal geometric alignment measurement, NOT a probability of profit. A 90% score simply means the structure is highly aligned to our model; it can still result in a financial loss."},{q:"Which markets does Axnna monitor?",a:"Currently, Axnna focuses on major foreign exchange instruments (EURUSD, GBPUSD, USDJPY) and Gold (XAUUSD)."},{q:"Can Axnna guarantee profits?",a:"Absolutely not. Trading involves substantial risk of loss. Axnna is a structural analysis tool, not a crystal ball."},{q:"What happens during major market events?",a:'Axnna incorporates a Fundamental Engine that actively monitors macroeconomic calendars (e.g., NFP, CPI, Central Bank decisions). If a critical event is imminent, Axnna categorizes it as "EXTREME EVENT RISK" and may suppress technical signals to prevent exposure to untradable volatility.'},{q:"How do I connect Telegram?",a:'Click the "Connect to Telegram" button. You will be provided with a unique connection payload. Send it to our official Telegram bot to link your account instantly.'}];return e.jsxs("div",{style:{maxWidth:"800px",margin:"0 auto",paddingBottom:"4rem"},children:[e.jsx("h1",{style:{fontSize:"3rem",fontWeight:700,letterSpacing:"-0.02em",marginBottom:"3rem"},children:"Frequently Asked Questions"}),e.jsx("div",{style:{display:"flex",flexDirection:"column",gap:"2rem"},children:a.map((n,t)=>e.jsxs("div",{style:{borderBottom:"1px solid var(--border-color)",paddingBottom:"2rem"},children:[e.jsx("h3",{style:{fontSize:"1.25rem",fontWeight:600,marginBottom:"0.75rem"},children:n.q}),e.jsx("p",{style:{color:"var(--text-muted)",lineHeight:1.6},children:n.a})]},t))})]})}export{i as default};
